import json, subprocess, sys

main_bin, head_bin = sys.argv[1], sys.argv[2]
corpora = {
    "mantine": "/Users/gabe/.cache/caliper/corpora/repos/mantine/packages/@mantine/core/src",
    "antd": "/Users/gabe/.cache/caliper/corpora/repos/ant-design/components",
}


def run(binary, src, cache):
    out = subprocess.run(
        [binary, "extract", "--src", src, "--quiet", "--no-cache", "--load-dependencies", "--json"],
        capture_output=True, text=True, check=True, cwd="/tmp/claude-501/cmp-cwd",
    ).stdout
    data = json.loads(out)
    data.pop("stats", None)
    return data


def non_info_backend(data):
    return [d for d in data.get("diagnostics", [])
            if d.get("code") == "SEMANTIC_BACKEND" and d.get("severity") != "info"]


for name, src in corpora.items():
    for i in range(2):
        a = run(main_bin, src, None)
        b = run(head_bin, src, None)
        dropped = non_info_backend(a) or non_info_backend(b)
        if dropped:
            print(name, i, "DROPPED non-info SEMANTIC_BACKEND", [(d.get("code"), d.get("severity")) for d in dropped])
            continue
        print(name, i, "identical" if a == b else "DIFFERENT",
              "components", len(a.get("components", {})), "diagnostics", len(a.get("diagnostics", [])))

